<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ArrowLeft, Delete, Edit, Link, Plus, Remove, Select } from '@element-plus/icons-vue'

const props = withDefaults(defineProps<{
  record: Record<string, any>
  categories: Array<{ id: number; name: string }>
  canManage?: boolean
  showPrice?: boolean
  startEditing?: boolean
}>(), { canManage: false, showPrice: false, startEditing: false })
const emit = defineEmits<{ back: []; save: [value: Record<string, any>]; savePrice: [value: Record<string, any>]; delete: []; relate: [kind: string]; openRelation: [relation: any] }>()
const editing = ref(false)
const draft = reactive<Record<string, any>>({})
const dynamicFields = ref<Array<{ key:string; value:string; unit:string; group:string; highlight:boolean; dataType:string }>>([])
const galleryText=ref(''),tagsText=ref(''),featuresText=ref(''),boundariesText=ref('')
const priceEditing=ref(false),priceDraft=reactive({reference_price:0,currency:'CNY',tax_included:true,tax_rate:13,valid_until:'',notes:''})
const productTypes = [{label:'硬件产品',value:'HARDWARE'},{label:'软件产品',value:'SOFTWARE_PRODUCT'},{label:'系统产品',value:'SYSTEM_PRODUCT'},{label:'配套设备',value:'ACCESSORY'}]
const typeName = computed(() => productTypes.find((item) => item.value === props.record.productType)?.label || '硬件产品')
const allRelations = computed(() => {
  const legacy = (props.record.capabilities || []).map((item:any) => ({ ...item, type: 'model-capabilities' }))
  const modern = props.record.relations || []
  const seen = new Set(modern.map((item:any) => item.type + ':' + item.id))
  return [...modern, ...legacy.filter((item:any) => !seen.has(item.type + ':' + item.id))]
})
const recommendations: Record<string, string[]> = {HARDWARE:['外形尺寸','工作温度','防护等级'],SOFTWARE_PRODUCT:['部署方式','操作系统','数据库'],SYSTEM_PRODUCT:['部署架构','适用规模','交付周期'],ACCESSORY:['接口类型','供电方式','安装方式']}
const quickMetrics=computed(()=>(props.record.parameters||[]).filter((item:any)=>item.highlight).sort((a:any,b:any)=>(a.sortOrder||0)-(b.sortOrder||0)).slice(0,6))
const gallery=computed(()=>props.record.gallery?.length?props.record.gallery:(props.record.mainImage?[{image:props.record.mainImage,title:props.record.name}]:[]))

function resetDraft() {
  Object.assign(draft, { name:props.record.name,product_type:props.record.productType,model_code:props.record.primaryModel||props.record.modelCode,product_code:props.record.productCode||'',product_series:props.record.productSeries||'',current_version:props.record.currentVersion||'',category_id:props.record.categoryId,summary:props.record.summary,description:props.record.description||'',status:props.record.status,data_status:props.record.dataStatus||'CONFIRMED',main_image:props.record.mainImage||'' })
  dynamicFields.value=(props.record.parameters||[]).map((item:any)=>({key:item.name,value:String(item.value||''),unit:item.unit||'',group:item.group||'基础参数',highlight:!!item.highlight,dataType:item.dataType||'TEXT'}))
  galleryText.value=(props.record.gallery||[]).map((item:any)=>[item.image,item.title||''].join('|')).join('\n')
  tagsText.value=(props.record.tags||[]).join('\n')
  featuresText.value=(props.record.features||[]).map((item:any)=>[item.title,item.description||'',item.icon||''].join('|')).join('\n')
  boundariesText.value=(props.record.boundaries||[]).join('\n')
}
function beginEdit(){resetDraft();editing.value=true}
function addField(key=''){dynamicFields.value.push({key,value:'',unit:'',group:'基础参数',highlight:false,dataType:'TEXT'})}
const textLines=(value:string)=>value.split('\n').map((item)=>item.trim()).filter(Boolean)
function save(){const parameters=dynamicFields.value.filter((item)=>item.key.trim()).map((item,index)=>({name:item.key.trim(),value:item.value,unit:item.unit,group:item.group,highlight:item.highlight,dataType:item.dataType,sortOrder:index}));const gallery=textLines(galleryText.value).map((line,index)=>{const[image,title='']=line.split('|');return{image,title,sortOrder:index}});const features=textLines(featuresText.value).map((line,index)=>{const[title,description='',icon='']=line.split('|');return{title,description,icon,sortOrder:index}});emit('save',{...draft,parameters,gallery,tags:textLines(tagsText.value),features,boundaries:textLines(boundariesText.value)});editing.value=false}
function beginPriceEdit(){Object.assign(priceDraft,{reference_price:props.record.price?.referencePrice||0,currency:props.record.price?.currency||'CNY',tax_included:props.record.price?.taxIncluded??true,tax_rate:props.record.price?.taxRate??13,valid_until:props.record.price?.validUntil?.slice(0,10)||'',notes:props.record.price?.notes||''});priceEditing.value=true}
function savePrice(){emit('savePrice',{...priceDraft,valid_until:priceDraft.valid_until||null});priceEditing.value=false}
watch(() => props.record.id, () => { resetDraft(); editing.value = props.startEditing }, { immediate: true })
watch(() => props.startEditing, (value) => { if(value)beginEdit() })
</script>

<template>
  <section class="product-detail-page">
    <div class="detail-nav"><el-button link :icon="ArrowLeft" @click="emit('back')">返回产品中心</el-button></div>
    <header class="product-hero">
      <div class="product-gallery"><div class="product-image"><img :src="record.mainImage||'/assets/product-radar.png'" :alt="record.name"></div><div v-if="gallery.length>1" class="gallery-thumbs"><img v-for="item in gallery.slice(0,4)" :key="item.image" :src="item.image" :alt="item.title||record.name"></div></div>
      <div><div class="eyebrow">{{ typeName }} · {{ record.category }}</div><h1>{{ record.name }}</h1><p>{{ record.summary || '暂无一句话简介' }}</p><div class="hero-tags"><el-tag type="success" effect="plain">{{ record.status==='ON_SALE'?'在售':'停售' }}</el-tag><el-tag effect="plain">主型号 {{ record.modelCode }}</el-tag><el-tag v-if="record.currentVersion" effect="plain">版本 {{ record.currentVersion }}</el-tag></div><div v-if="quickMetrics.length" class="quick-metrics"><div v-for="item in quickMetrics" :key="item.id||item.name"><span>{{ item.name }}</span><strong>{{ item.value }}{{ item.unit }}</strong></div></div></div>
      <div v-if="canManage" class="hero-actions"><el-button v-if="!editing" :icon="Edit" @click="beginEdit">编辑产品</el-button><el-button type="danger" plain :icon="Delete" @click="emit('delete')">删除</el-button></div>
    </header>

    <div v-if="editing" class="edit-banner"><span>正在编辑产品知识</span><div><el-button @click="editing=false">取消</el-button><el-button type="primary" :icon="Select" @click="save">保存修改</el-button></div></div>

    <div class="product-layout">
      <main>
        <section class="product-section"><div class="section-head"><div><h2>产品概览</h2><p>基础身份、分类与销售状态。</p></div></div>
          <el-form v-if="editing" label-position="top" class="edit-grid"><el-form-item label="产品名称"><el-input v-model="draft.name" /></el-form-item><el-form-item label="产品类型"><el-select v-model="draft.product_type"><el-option v-for="item in productTypes" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="产品编码"><el-input v-model="draft.product_code" /></el-form-item><el-form-item label="产品系列"><el-input v-model="draft.product_series" /></el-form-item><el-form-item label="主型号"><el-input v-model="draft.model_code" /></el-form-item><el-form-item label="当前版本"><el-input v-model="draft.current_version" /></el-form-item><el-form-item label="分类"><el-select v-model="draft.category_id"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="销售状态"><el-select v-model="draft.status"><el-option label="在售" value="ON_SALE"/><el-option label="停售" value="OFF_SALE"/></el-select></el-form-item><el-form-item label="数据状态"><el-select v-model="draft.data_status"><el-option label="已确认" value="CONFIRMED"/><el-option label="待确认" value="PENDING"/></el-select></el-form-item><el-form-item label="主图地址"><el-input v-model="draft.main_image" /></el-form-item><el-form-item label="一句话简介" class="span-2"><el-input v-model="draft.summary" type="textarea" :rows="2" /></el-form-item><el-form-item label="详细介绍" class="span-2"><el-input v-model="draft.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="图片图库" class="span-2"><el-input v-model="galleryText" type="textarea" placeholder="每行：图片地址|图片标题" /></el-form-item><el-form-item label="产品标签" class="span-2"><el-input v-model="tagsText" type="textarea" placeholder="每行一个标签" /></el-form-item><el-form-item label="主要特性" class="span-2"><el-input v-model="featuresText" type="textarea" placeholder="每行：特性名称|说明|图标名" /></el-form-item><el-form-item label="能力边界" class="span-2"><el-input v-model="boundariesText" type="textarea" placeholder="每行一项" /></el-form-item></el-form>
          <template v-else><el-descriptions :column="2" border><el-descriptions-item label="产品编码">{{ record.productCode||'-' }}</el-descriptions-item><el-descriptions-item label="产品系列">{{ record.productSeries||'-' }}</el-descriptions-item><el-descriptions-item label="产品类型">{{ typeName }}</el-descriptions-item><el-descriptions-item label="分类">{{ record.category }}</el-descriptions-item><el-descriptions-item label="主型号">{{ record.modelCode }}</el-descriptions-item><el-descriptions-item label="当前版本">{{ record.currentVersion||'-' }}</el-descriptions-item><el-descriptions-item label="销售状态">{{ record.status==='ON_SALE'?'在售':'停售' }}</el-descriptions-item><el-descriptions-item label="数据状态">{{ record.dataStatus==='PENDING'?'待确认':'已确认' }}</el-descriptions-item></el-descriptions><p v-if="record.description" class="product-description">{{ record.description }}</p><div v-if="record.features?.length" class="feature-grid"><article v-for="item in record.features" :key="item.id||item.title"><strong>{{ item.title }}</strong><p>{{ item.description }}</p></article></div><div v-if="record.boundaries?.length" class="boundary-box"><h3>能力边界</h3><ul><li v-for="item in record.boundaries" :key="item">{{ item }}</li></ul></div></template>
        </section>

        <section class="product-section"><div class="section-head"><div><h2>产品参数</h2><p>字段根据产品类型推荐，产品经理可直接增删。</p></div><el-dropdown v-if="editing" trigger="click" @command="addField"><el-button :icon="Plus">添加推荐字段</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="field in recommendations[draft.product_type]||[]" :key="field" :command="field">{{ field }}</el-dropdown-item><el-dropdown-item divided command="">自定义字段</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
          <div v-if="editing" class="dynamic-editor"><div v-for="(field,index) in dynamicFields" :key="index"><el-input v-model="field.key" placeholder="字段名称"/><el-input v-model="field.value" placeholder="字段内容"/><el-input v-model="field.unit" placeholder="单位"/><el-input v-model="field.group" placeholder="参数分组"/><el-select v-model="field.dataType" aria-label="数据类型"><el-option label="文本" value="TEXT"/><el-option label="数值" value="NUMBER"/><el-option label="布尔" value="BOOLEAN"/></el-select><el-checkbox v-model="field.highlight" label="重点"/><el-button :icon="Remove" circle aria-label="删除字段" @click="dynamicFields.splice(index,1)"/></div><el-empty v-if="!dynamicFields.length" description="暂无参数字段" :image-size="56" /></div>
          <el-descriptions v-else-if="record.parameters?.length" :column="2" border><el-descriptions-item v-for="item in record.parameters" :key="item.id||item.name" :label="item.name">{{ item.value }}{{ item.unit }}</el-descriptions-item></el-descriptions><el-empty v-else description="暂无产品参数" :image-size="64" />
        </section>

        <section class="product-section"><div class="section-head"><div><h2>关联知识</h2><p>模型能力、软件、算法、场景与方案的真实关联。</p></div><el-button v-if="canManage" :icon="Link" @click="emit('relate','all')">选择关联</el-button></div><div v-if="allRelations.length" class="relation-grid"><button v-for="relation in allRelations" :key="relation.type+relation.id" @click="emit('openRelation',relation)"><strong>{{ relation.name }}</strong><small>{{ relation.category || relation.summary || '查看关联详情' }}</small></button></div><el-empty v-else description="暂无关联知识" :image-size="64" /></section>

        <section v-if="showPrice" class="product-section"><div class="section-head"><div><h2>价格信息</h2><p>仅具备价格查看权限的用户可见。</p></div><el-button v-if="canManage&&!priceEditing" :icon="Edit" @click="beginPriceEdit">维护价格</el-button></div><el-form v-if="priceEditing" label-position="top" class="edit-grid"><el-form-item label="参考价格"><el-input-number v-model="priceDraft.reference_price" :min="0" :precision="2" style="width:100%"/></el-form-item><el-form-item label="币种"><el-select v-model="priceDraft.currency"><el-option label="人民币" value="CNY"/></el-select></el-form-item><el-form-item label="含税"><el-switch v-model="priceDraft.tax_included"/></el-form-item><el-form-item label="税率 (%)"><el-input-number v-model="priceDraft.tax_rate" :min="0" :max="100"/></el-form-item><el-form-item label="有效期"><el-date-picker v-model="priceDraft.valid_until" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="备注"><el-input v-model="priceDraft.notes"/></el-form-item><div class="span-2 price-actions"><el-button @click="priceEditing=false">取消</el-button><el-button type="primary" @click="savePrice">保存价格</el-button></div></el-form><div v-else-if="record.price" class="price-value"><span>参考价格{{ record.price.taxIncluded?'（含税）':'（未税）' }}</span><strong>{{ record.price.currency }} {{ Number(record.price.referencePrice).toLocaleString() }}</strong></div><el-empty v-else description="暂无价格信息" :image-size="56" /></section>
      </main>
      <aside class="product-aside"><h3>维护信息</h3><dl><div><dt>创建来源</dt><dd>{{ record.source || '产品中心' }}</dd></div><div><dt>最近更新</dt><dd>{{ new Date(record.updatedAt).toLocaleDateString() }}</dd></div><div><dt>记录编号</dt><dd>#{{ record.id }}</dd></div></dl></aside>
    </div>
  </section>
</template>

<style scoped>
.product-detail-page{display:grid;gap:14px}.detail-nav{height:28px}.product-hero{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:22px;align-items:start;padding:24px;background:#fff;border:1px solid #e2e9f2;border-radius:8px}.product-gallery{display:grid;gap:7px}.product-image{display:grid;place-items:center;width:150px;height:118px;overflow:hidden;border-radius:8px;background:#eaf3ff;color:#146ef5;font-size:36px;font-weight:700}.product-image img{width:100%;height:100%;object-fit:cover}.gallery-thumbs{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.gallery-thumbs img{width:100%;height:30px;object-fit:cover;border:1px solid #e1e8f0;border-radius:4px}.eyebrow{font-size:12px;color:#146ef5;font-weight:700}.product-hero h1{margin:6px 0;font-size:26px;letter-spacing:0;color:#14233c}.product-hero p{margin:0;color:#66758d}.hero-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.quick-metrics{display:grid;grid-template-columns:repeat(3,minmax(90px,1fr));gap:8px;margin-top:14px}.quick-metrics div{display:grid;gap:2px;padding:8px 10px;background:#f5f9ff;border-radius:6px}.quick-metrics span{font-size:11px;color:#748397}.quick-metrics strong{font-size:14px;color:#173257}.hero-actions{display:flex;gap:8px}.edit-banner{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:#eaf3ff;border:1px solid #bdd7ff;border-radius:8px;color:#1557aa;font-weight:600}.product-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:16px}.product-layout main{display:grid;gap:16px}.product-section,.product-aside{padding:20px;background:#fff;border:1px solid #e2e9f2;border-radius:8px}.section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:16px}.section-head h2,.product-aside h3{margin:0;font-size:17px;letter-spacing:0;color:#192941}.section-head p{margin:5px 0 0;font-size:13px;color:#78869a}.product-description{margin:16px 0 0;color:#52637b;line-height:1.75}.feature-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:16px}.feature-grid article{padding:13px;background:#f7f9fc;border:1px solid #e7edf4;border-radius:7px}.feature-grid strong{color:#21354f}.feature-grid p{margin:5px 0 0;font-size:13px;line-height:1.6;color:#6d7c90}.boundary-box{margin-top:16px;padding:14px;background:#f7fafc;border-left:3px solid #10b7b0}.boundary-box h3{margin:0 0 8px;font-size:14px}.boundary-box ul{margin:0;padding-left:20px;color:#5e6f84;line-height:1.7}.edit-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.edit-grid .span-2{grid-column:1/-1}.edit-grid :deep(.el-select){width:100%}.dynamic-editor{display:grid;gap:10px}.dynamic-editor>div{display:grid;grid-template-columns:150px minmax(120px,1fr) 80px 120px 100px 64px 34px;gap:8px;align-items:center}.relation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.relation-grid button{display:grid;gap:4px;padding:13px;text-align:left;background:#f8fafc;border:1px solid #e3eaf2;border-radius:7px;cursor:pointer}.relation-grid strong{color:#20324b}.relation-grid small{color:#758398}.price-value{display:flex;align-items:baseline;justify-content:space-between;padding:18px;background:#f5f9ff;border-radius:7px}.price-value span{color:#6f7e92}.price-value strong{font-size:24px;color:#146ef5}.product-aside{align-self:start}.product-aside dl{margin:14px 0 0}.product-aside dl div{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #edf1f5;font-size:13px}.product-aside dt{color:#78869a}.product-aside dd{margin:0;color:#273950;text-align:right}@media(max-width:1200px){.dynamic-editor>div{grid-template-columns:repeat(3,minmax(0,1fr)) 34px}.dynamic-editor>div :nth-child(7){grid-column:4}}@media(max-width:1000px){.product-layout{grid-template-columns:1fr}.product-aside{order:-1}.relation-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.product-hero{grid-template-columns:1fr}.product-image{width:100%;height:180px}.hero-actions{grid-column:1/-1}.quick-metrics,.feature-grid{grid-template-columns:1fr 1fr}.edit-grid{grid-template-columns:1fr}.edit-grid .span-2{grid-column:auto}.dynamic-editor>div{grid-template-columns:1fr 1fr}.dynamic-editor>div :nth-child(7){grid-column:auto}.relation-grid{grid-template-columns:1fr}}
.price-actions{display:flex;justify-content:flex-end;gap:8px}
</style>
